'use strict';
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

// Obsidian supplies these modules. All project modules are included in main.js.
const EXTERNALS = new Set(['obsidian', '@codemirror/view']);

function bundle(entry, sourceRoot) {
  const modules = new Map();
  const root = path.resolve(sourceRoot);
  function visit(filename) {
    const absolute = path.resolve(filename);
    const id = path.relative(root, absolute).split(path.sep).join('/');
    if (id.startsWith('../') || path.isAbsolute(id))
      throw new Error(`Module outside src/: ${filename}`);
    if (modules.has(id)) return id;
    const source = fs.readFileSync(absolute, 'utf8');
    new vm.Script(source, { filename: absolute });
    modules.set(id, '');
    // Project imports use static CommonJS calls; no dynamic loading or npm runtime.
    const dependencies = {};
    for (const [, , name] of source.matchAll(/\brequire\((['"])([^'"]+)\1\)/g)) {
      if (!name.startsWith('.')) {
        if (!EXTERNALS.has(name)) throw new Error(`Unsupported external module: ${name}`);
        continue;
      }
      const target = path.resolve(path.dirname(absolute), name);
      dependencies[name] = visit(path.extname(target) ? target : target + '.js');
    }
    modules.set(id, { source, dependencies });
    return id;
  }
  const entryId = visit(entry);
  const factories = [...modules].map(
    ([id, { source, dependencies }]) =>
      `${JSON.stringify(id)}: { dependencies: ${JSON.stringify(dependencies)},\n` +
      `run: (module, exports, require) => {\n${source}\n} }`,
  );
  const result =
    `// PikoBoard — generated by npm run build; edit src/ instead.\n` +
    `'use strict';\nconst factories = {\n${factories.join(',\n')}\n};\n` +
    `const cache = Object.create(null);\n` +
    `function load(id) {\n` +
    `  if (cache[id]) return cache[id].exports;\n` +
    `  const module = { exports: {} };\n` +
    `  cache[id] = module;\n` +
    `  const factory = factories[id];\n` +
    `  factory.run(module, module.exports, (name) =>\n` +
    `    Object.hasOwn(factory.dependencies, name) ? load(factory.dependencies[name]) : require(name),\n` +
    `  );\n` +
    `  return module.exports;\n` +
    `}\nmodule.exports = load(${JSON.stringify(entryId)});\n`;
  new vm.Script(result, { filename: 'main.js' });
  return result;
}

module.exports = { bundle };
